9: var isRegExp = require('util').isRegExp;
10: 
11: // Generate an internal UID to make the regexp pattern harder to guess.
12: var UID                 = Math.floor(Math.random() * 0x10000000000).toString(16);
13: var PLACE_HOLDER_REGEXP = new RegExp('"@__(FUNCTION|REGEXP)-' + UID + '-(\\d+)__@"', 'g');
14: 
15: var IS_NATIVE_CODE_REGEXP = /\{\s*\[native code\]\s*\}/g;
16: var UNSAFE_CHARS_REGEXP   = /[<>\/\u2028\u2029]/g;
17: 
18: // Mapping of unsafe HTML and invalid JavaScript line terminator chars to their
19: // Unicode char counterparts which are safe to use in JavaScript strings.
20: var UNICODE_CHARS = {
21:     '<'     : '\\u003C',
22:     '>'     : '\\u003E',
23:     '/'     : '\\u002F',
24:     '\u2028': '\\u2028',
25:     '\u2029': '\\u2029'
26: };
27: 
28: // There's an issue with Node 0.10 (V8 3.14.5.9) which causes `JSON.stringify()`
29: // and the subsequent `str.replace()` call to take over 100x more time than when
30: // a the `JSON.stringify()` replacer function is used and the data being
31: // serialized is very large (500KB). A remedy to this is setting the
32: // `JSON.stringify()` `space` option to a truthy value.
33: var SPACE = 2;
34: 
35: module.exports = function serialize(obj) {
36:     var functions = [];
37:     var regexps   = [];
38:     var str;
39: 
40:     // Creates a JSON string representation of the object and uses placeholders
41:     // for functions and regexps (identified by index) which are later
42:     // replaced.
43:     str = JSON.stringify(obj, function (key, value) {
44:         if (typeof value === 'function') {
45:             return '@__FUNCTION-' + UID + '-' + (functions.push(value) - 1) + '__@';
46:         }
47: 
48:         if (typeof value === 'object' && isRegExp(value)) {
49:             return '@__REGEXP-' + UID + '-' + (regexps.push(value) - 1) + '__@';
50:         }
51: 
52:         return value;
53:     }, SPACE);
54: 
55:     // Protects against `JSON.stringify()` returning `undefined`, by serializing
56:     // to the literal string: "undefined".
57:     if (typeof str !== 'string') {
58:         return String(str);
59:     }
60: 
61:     // Replace unsafe HTML and invalid JavaScript line terminator chars with
62:     // their safe Unicode char counterpart. This _must_ happen before the
63:     // regexps and functions are serialized and added back to the string.
64:     str = str.replace(UNSAFE_CHARS_REGEXP, function (unsafeChar) {
65:         return UNICODE_CHARS[unsafeChar];
66:     });
67: 
68:     if (functions.length === 0 && regexps.length === 0) {
69:         return str;
70:     }
71: 
72:     // Replaces all occurrences of function and regexp placeholders in the JSON
73:     // string with their string representations. If the original value can not
74:     // be found, then `undefined` is used.
75:     return str.replace(PLACE_HOLDER_REGEXP, function (match, type, valueIndex) {
76:         if (type === 'REGEXP') {
77:             return regexps[valueIndex].toString();
78:         }
79: 
80:         var fn           = functions[valueIndex];
81:         var serializedFn = fn.toString();
82: 
83:         if (IS_NATIVE_CODE_REGEXP.test(serializedFn)) {
84:             throw new TypeError('Serializing native function: ' + fn.name);
85:         }
86: 
87:         return serializedFn;
88:     });
89: }

